# d)
list_logs = logs.split("\n")
dia_hora = []
for i in list_logs:
    letras1 = ""
    for e in i:
        if e != " ":
            letras1 += e
        else:
            dia_hora.append(letras1)
            break
horas = []
for i in dia_hora:
    hora = i[12: -1]
    hora_min = ""
    if len(hora) == 7:
        hora_min = hora[3:5]
    horas.append(hora_min)
regis = {}
for hora in horas:
    regis[hora] = regis.get(hora,0) + 1
for i in regis:
    print(f"Houve {regis[i]} registros nos minutos {i}")
